def pack(data, start_bit, length, value):
    for i in range(length):
        byte, pos = divmod(start_bit + i, 8)
        if (value >> i) & 1: data[byte] |= 1 << pos
        else:                data[byte] &= ~(1 << pos)

def unpack(data, start_bit, length):
    v = 0
    for i in range(length):
        byte, pos = divmod(start_bit + i, 8)
        v |= ((data[byte] >> pos) & 1) << i
    return v

frame = bytearray(8)
pack(frame, 4, 12, int(87.5 / 0.0625))   # 1400
pack(frame, 16, 2, 0b10)
print(frame.hex(' '))                     # 80 57 02 00 00 00 00 00
print(unpack(frame, 4, 12) * 0.0625, unpack(frame, 16, 2))  # 87.5 2

def mixed(events, period=100, min_delay=20, until=300):
    sent, last, pending = [], -10**9, sorted(events)
    for t in range(until + 1):
        due = t % period == 0
        ev = bool(pending) and pending[0] <= t
        if (due or ev) and t - last >= min_delay:
            sent.append(t); last = t
            while pending and pending[0] <= t: pending.pop(0)
    return sent

print(mixed([35, 42, 150]))   # [0, 35, 55, 100, 150, 200, 300]
